# All PPL data from registry (verified)
data = {
    "Uniform": {
        "params": "",
        "seeds": {42: 17.690, 123: 17.690, 456: 17.700},
        "note": ""
    },
    "Grid b=0.5": {
        "params": "b=0.5",
