        "seeds": {42: 17.692, 123: 17.674, 456: 17.680},
        "note": ""
    },
    "Grid b=1.5": {
        "params": "b=1.5",
        "seeds": {42: 17.718, 123: 17.701, 456: 17.710},
        "note": ""
    },
    "Grid b=2.0": {
        "params": "b=2.0",
        "seeds": {42: 17.741, 123: 17.725},
        "note": "seed456 invalidated (D026)"
    },
    "Grid b=3.0": {
        "params": "b=3.0",
        "seeds": {42: 17.774, 123: 17.760},
        "note": "seed456 invalidated (D026)"
    },
    "Grid b=5.0": {
        "params": "b=5.0",
        "seeds": {42: 17.818, 123: 17.804},
        "note": "seed456 invalidated (D026)"
    },
    "Adaptive (n_min=3)": {
        "params": "tau=0.8, n_min=3",
        "seeds": {42: 17.690, 123: 17.630, 456: 17.640},
        "note": "original, has n_min=3 bug"
    },
    "Adaptive-fix (n_min=2)": {
        "params": "tau=0.8, n_min=2",
        "seeds": {42: 17.650, 123: 17.643, 456: 17.660},
        "note": ""
    },
}

def mean(vals):
    return sum(vals) / len(vals)

def sample_std(vals):
    m = mean(vals)
    if len(vals) < 2:
        return 0.0
    return math.sqrt(sum((v - m)**2 for v in vals) / (len(vals) - 1))

# Compute uniform baseline mean
uniform_mean = mean(list(data["Uniform"]["seeds"].values()))

results = []
for method, d in data.items():
    vals = list(d["seeds"].values())
    m = mean(vals)
    s = sample_std(vals)
    delta = uniform_mean - m  # positive = improvement
    pct = (delta / uniform_mean) * 100
    n_seeds = len(vals)
    results.append({
        "method": method,
        "params": d["params"],
        "n_seeds": n_seeds,
        "seeds": d["seeds"],
        "mean": m,
        "std": s,
        "delta": delta,
        "pct": pct,
        "note": d["note"]
    })

# Print for verification
print(f"Uniform baseline mean: {uniform_mean:.3f}")
print()
for r in results:
    seed_str = " | ".join(f"s{k}={v:.3f}" for k, v in r["seeds"].items())
    print(f"{r['method']:25s} | {seed_str} | mean={r['mean']:.3f} ± {r['std']:.3f} | Δ={r['delta']:+.3f} ({r['pct']:+.1f}%) | n={r['n_seeds']}")
    if r["note"]:
        print(f"{'':25s}   NOTE: {r['note']}")

# Save as JSON for artifact generation
output = {
    "uniform_baseline_mean": round(uniform_mean, 3),
    "results": []
}
for r in results:
    output["results"].append({
        "method": r["method"],
        "params": r["params"],
        "n_seeds": r["n_seeds"],
        "per_seed": {str(k): round(v, 3) for k, v in r["seeds"].items()},
        "mean_ppl": round(r["mean"], 3),
        "std_ppl": round(r["std"], 3),
        "delta_ppl": round(r["delta"], 3),
        "pct_improvement": round(r["pct"], 1),
        "note": r["note"]
    })

print("\n" + json.dumps(output, indent=2))
PYEOF
